{"content":"import 'package:mad_flutter_practicum/app/app.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;
  int _refreshCounter = 0;

  Widget get _currencyPage => CurrencyListPage(key: ObjectKey('_c_$_refreshCounter'));
  Widget get _newsPage => NewsListPage(key: ObjectKey('_n_$_refreshCounter'));

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  void _onRefreshAll() {
    setState(() {
      _refreshCounter++;
    });
  }

  @override
  Widget build(BuildContext context) {
    final List<Widget> pages = <Widget>[
      _currencyPage,
      _newsPage,
      ProfilePage(),
    ];
    final Widget currentPage = pages[_selectedIndex];
    final AppLocalizations loc = context.loc;

    return Scaffold(
      body: currentPage,
      appBar: AppBar(
        title: Text(loc.currencyRate),
        actions: <Widget>[
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: loc.refreshAll,
            onPressed: _onRefreshAll,
          ),
        ],
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 10,
              offset: const Offset(0.0, 4.0),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          type: BottomNavigationBarType.fixed,
          items: <BottomNavigationBarItem>[
            BottomNavigationBarItem(
              icon: Icon(Icons.swap_horiz),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: Icon(Icons.article),
              label: loc.news,
            ),
            const BottomNavigationBarItem(
              icon: Icon(Icons.person),
              label: 'profile',
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) => const SizedBox.shrink();
}
